@UnstableApi public static ListenableFuture<SessionToken> createSessionToken(Context context,Object compatToken){
  checkNotNull(context,"context must not be null");
  checkNotNull(compatToken,"compatToken must not be null");
  checkArgument(compatToken instanceof MediaSessionCompat.Token);
  HandlerThread thread=new HandlerThread("SessionTokenThread");
  thread.start();
  SettableFuture<SessionToken> future=SettableFuture.create();
  try {
    MediaControllerCompat controller=createMediaControllerCompat(context,(MediaSessionCompat.Token)compatToken);
    String packageName=controller.getPackageName();
    int uid=getUid(context.getPackageManager(),packageName);
    Handler handler=new Handler(thread.getLooper());
    controller.sendCommand(MediaConstants.SESSION_COMMAND_REQUEST_SESSION3_TOKEN,null,new ResultReceiver(handler){
      @Override protected void onReceiveResult(      int resultCode,      Bundle resultData){
        handler.removeCallbacksAndMessages(null);
        future.set(SessionToken.CREATOR.fromBundle(resultData));
      }
    }
    );
    handler.postDelayed(() -> {
      SessionToken resultToken=new SessionToken(new SessionTokenImplLegacy((MediaSessionCompat.Token)compatToken,packageName,uid,controller.getSessionInfo()));
      future.set(resultToken);
    }
    ,WAIT_TIME_MS_FOR_SESSION3_TOKEN);
    future.addListener(() -> thread.quit(),MoreExecutors.directExecutor());
    return future;
  } catch (RuntimeException e) {
    future.setException(e);
    thread.quit();
    return future;
  }
}
